@push('scripts')<script>$(function(){const t=$('#material-movements-table'),x=$.fn.dataTable.render.text(),num=$.fn.dataTable.render.number(',','.',2),classes={DRAFT:'app-status-neutral',APPROVED:'app-status-info',POSTED:'app-status-success',VOID:'app-status-danger',REVERSED:'app-status-danger'},dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.status=$('#movement-status').val();d.date_from=$('#movement-from').val();d.date_to=$('#movement-to').val();}},order:[[7,'desc']],buttons:[window.erpExcelButton(t)],columns:[window.erpRowNumberColumn(),{data:'document_number',name:'document_number',render:function(v,z,r){return z==='display'?'<a href="'+x.display(r.show_url)+'">'+x.display(v)+'</a>':v;}},{data:'movement_type',name:'movement_type',render:x.display},{data:'item_label',name:'item_label',render:x.display},{data:'uom_label',name:'uom_label',render:x.display},{data:'quantity',name:'quantity',className:'text-end',render:num},{data:'value',name:'value',className:'text-end',render:function(v,z){return z==='display'&&v!==null?num.display(v):v;}},{data:'document_date',name:'document_date',render:x.display},{data:'status',name:'status',render:function(v,z){return z==='display'?'<span class="badge '+(classes[v]||'app-status-neutral')+'">'+x.display(v)+'</span>':v;}},{data:'reason',name:'reason',render:x.display},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,z,r){return z==='display'?'<a class="btn btn-sm btn-app-soft" href="'+x.display(r.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-show" aria-hidden="true"></i></a>':'';}}]}));$('#movement-filters').on('submit',function(e){e.preventDefault();dt.ajax.reload();});$('#movement-reset').on('click',function(){$('#movement-filters')[0].reset();dt.ajax.reload();});});</script>@endpush
